    Bug 1988690 - Improve fakeserver line reading. r=tobyp

    Doing this in a for loop rather than a recursive function call is much faster and uses less memory.

    Differential Revision: https://phabricator.services.mozilla.com/D267116

diff --git a/mailnews/test/fakeserver/Maild.sys.mjs b/mailnews/test/fakeserver/Maild.sys.mjs
index 1af8855e9bc..9ee72582b84 100644
--- a/mailnews/test/fakeserver/Maild.sys.mjs
+++ b/mailnews/test/fakeserver/Maild.sys.mjs
@@ -399,25 +399,17 @@ class nsMailReader {
   }

   _findLines() {
-    var buf = this._buffer;
-    for (
-      var crlfLoc = buf.indexOf(13);
-      crlfLoc >= 0;
-      crlfLoc = buf.indexOf(13, crlfLoc + 1)
-    ) {
-      if (buf[crlfLoc + 1] == 10) {
-        break;
+    let last = 0;
+    for (let i = 0; i < this._buffer.length; i++) {
+      if (this._buffer[i] == 13 && this._buffer[i + 1] == 10) {
+        this._lines.push(
+          String.fromCharCode.apply(null, this._buffer.slice(last, i))
+        );
+        last = i + 2;
       }
     }
-    if (crlfLoc == -1) {
-      // We failed to find a newline
-      return;
-    }

-    var line = String.fromCharCode.apply(null, buf.slice(0, crlfLoc));
-    this._buffer = buf.slice(crlfLoc + 2);
-    this._lines.push(line);
-    this._findLines();
+    this._buffer = this._buffer.slice(last);
   }

   onInputStreamReady(stream) {
